import { ApprovalWorkbench } from '@refy-design/web';
import type { ApprovalWorkbenchItem } from '@refy-design/web';
import { Card } from '@refy-design/web';
import { SectionHeader } from '@refy-design/web';
import { useState } from 'react';
const items: ApprovalWorkbenchItem[] = [
  {
    id: 'company',
    label: 'Company details',
    meta: '3 of 3 reviewed',
    state: 'complete',
  },
  { id: 'address', label: 'Address', meta: '1 of 3 reviewed', state: 'in-progress' },
  {
    id: 'registration',
    label: 'Professional license',
    meta: '0 of 3 reviewed',
    state: 'not-started',
  },
];
export function Example() {
  const [active, setActive] = useState('address');
  const item = items.find((entry) => entry.id === active) ?? items[0];
  return (
    <ApprovalWorkbench items={items} activeId={active} onActiveChange={setActive}>
      <Card>
        <SectionHeader
          title={item.label}
          sub="Check the sources and record the result of each criterion."
        />
      </Card>
    </ApprovalWorkbench>
  );
}

import { ApprovalWorkbench } from '@refy-design/web';
import type { ApprovalWorkbenchItem } from '@refy-design/web';
import { EmptyState } from '@refy-design/web';
import type { ComponentProps } from 'react';
const items: ApprovalWorkbenchItem[] = [
  {
    id: 'company',
    label: 'Company details',
    meta: '3 of 3 reviewed',
    state: 'complete',
  },
  { id: 'address', label: 'Address', meta: '1 of 3 reviewed', state: 'in-progress' },
  {
    id: 'registration',
    label: 'Professional license',
    meta: '0 of 3 reviewed',
    state: 'not-started',
  },
];
export function Example() {
  const args: Pick<
    ComponentProps<typeof ApprovalWorkbench>,
    'items' | 'activeId' | 'onActiveChange' | 'children'
  > = {
    items: items.map((item) => ({
      ...item,
      meta: '3 of 3 reviewed',
      state: 'complete',
    })),
    activeId: 'company',
    onActiveChange: () => undefined,
    children: (
      <EmptyState
        title="Review complete"
        message="Every item has a result and a note."
      />
    ),
  };
  return <ApprovalWorkbench {...args} />;
}

